#include "protocol.h"
#include <limits.h>
#include <string.h>
static bool num(const char*s,size_t n,int*v){if(!n)return false;int r=0,sign=1;size_t i=0;if(s[0]=='-'){sign=-1;i=1;if(n==1)return false;}for(;i<n;i++){if(s[i]<'0'||s[i]>'9'||r>(INT_MAX-9)/10)return false;r=r*10+s[i]-'0';}*v=r*sign;return true;}
static bool eq(const char*s,size_t n,const char*x){return strlen(x)==n&&!memcmp(s,x,n);}
static bool sess(const char*s,size_t n,char*out){if(n!=16)return false;for(size_t i=0;i<n;i++)if(!((s[i]>='0'&&s[i]<='9')||(s[i]>='a'&&s[i]<='f')))return false;memcpy(out,s,16);out[16]=0;return true;}
static bool key(const char*s,size_t n,flowdesk_key_t*k){static const char*names[]={"enter","tab","backspace","delete","left","right","up","down","home","end","ctrl+a","shift","escape","pagedown"};for(unsigned i=0;i<14;i++)if(eq(s,n,names[i])){*k=(flowdesk_key_t)i;return true;}return false;}
bool flowdesk_parse_frame(const char*f,size_t len,flowdesk_command_t*out,const char**e){const char*p[5];size_t z[5],b=0,c=0;if(!f||!out||!len||len>FLOWDESK_FRAME_MAX)goto bad;for(size_t i=0;i<=len;i++){if(i==len||f[i]=='\t'){if(c==5)goto bad;p[c]=f+b;z[c++]=i-b;b=i+1;}else if(f[i]=='\r'||f[i]=='\n')goto bad;}int id;if(c<2||!num(p[0],z[0],&id)||id<1)goto bid;memset(out,0,sizeof(*out));out->id=(uint32_t)id;if(c==2&&eq(p[1],z[1],"hello")){out->kind=FLOWDESK_HELLO;return true;}if(c==2&&eq(p[1],z[1],"status")){out->kind=FLOWDESK_STATUS;return true;}if(c==2&&eq(p[1],z[1],"disarm")){out->kind=FLOWDESK_DISARM;return true;}if(c==3&&eq(p[1],z[1],"begin")&&sess(p[2],z[2],out->session)){out->kind=FLOWDESK_BEGIN;return true;}if(c==3&&eq(p[1],z[1],"ping")&&sess(p[2],z[2],out->session)){out->kind=FLOWDESK_PING;return true;}if(c<3||!sess(p[2],z[2],out->session))goto bad;if(c==5&&eq(p[1],z[1],"move")){int x,y;if(!num(p[3],z[3],&x)||!num(p[4],z[4],&y)||x < -127||x>127||y < -127||y>127)goto range;out->kind=FLOWDESK_MOVE;out->x=x;out->y=y;return true;}if(c==4&&eq(p[1],z[1],"wheel")){int d;if(!num(p[3],z[3],&d)||d < -127||d>127)goto range;out->kind=FLOWDESK_WHEEL;out->y=d;return true;}if(c==4&&eq(p[1],z[1],"click")&&(eq(p[3],z[3],"left")||eq(p[3],z[3],"right"))){out->kind=FLOWDESK_CLICK;out->right=eq(p[3],z[3],"right");return true;}if(c==3&&eq(p[1],z[1],"paste")){out->kind=FLOWDESK_PASTE;return true;}if(c==4&&eq(p[1],z[1],"key")&&key(p[3],z[3],&out->key)){out->kind=FLOWDESK_KEY;return true;}if(c==4&&eq(p[1],z[1],"text")){if(z[3]>64)goto range;for(size_t i=0;i<z[3];i++)if(p[3][i]<32||p[3][i]>126)goto bad;memcpy(out->text,p[3],z[3]);out->kind=FLOWDESK_TEXT;return true;}bad:*e="malformed";return false;bid:*e="bad_id";return false;range:*e="range";return false;}
